package com.nigson.commerce.pricing;
import java.util.*;
import java.math.*;
import tools.jackson.databind.JsonNode;
import com.nigson.shared.problem.ApiValues;
import com.nigson.shared.events.EventCodec;
/** Canonical shared local carrier binding. One SKU per carton; bounded expansion before allocation. */
public final class CarrierPacking {
 private CarrierPacking(){}
 public record Item(UUID skuId,BigDecimal quantity,int scale,JsonNode packaging){}
 public record Parcel(UUID skuId,String quantity,String weightKg,String lengthCm,String widthCm,String heightCm){}
 public record Address(String recipient,String phone,String line1,String line2,String city,String region,String postalCode,String countryCode){public Address{try{com.nigson.commerce.party.PartyValues.text(recipient,160,false);com.nigson.commerce.party.PartyValues.text(line1,200,false);com.nigson.commerce.party.PartyValues.text(line2,200,true);com.nigson.commerce.party.PartyValues.text(city,100,false);com.nigson.commerce.party.PartyValues.text(region,100,false);com.nigson.commerce.party.PartyValues.text(postalCode,24,true);if(phone==null||!phone.matches("\\+[1-9][0-9]{7,14}")||!"NG".equals(countryCode))throw ApiValues.invalid();}catch(com.nigson.shared.problem.Problem.Failure invalid){throw PricingValues.rule();}}}
 public static List<Parcel> pack(List<Item> items){if(items==null||items.isEmpty()||items.size()>100)throw PricingValues.rule();var result=new ArrayList<Parcel>();var ids=new HashSet<UUID>();for(var item:items.stream().sorted(Comparator.comparing(i->i.skuId().toString())).toList()){if(!ids.add(item.skuId()))throw PricingValues.rule();var rule=item.packaging();try{com.nigson.commerce.market.MarketValues.closed(rule,Set.of("schemaVersion","maximumUnitsPerPackage","unitWeightKg","tareWeightKg","lengthCm","widthCm","heightCm"));if(!rule.get("schemaVersion").isIntegralNumber()||!rule.get("schemaVersion").canConvertToInt()||rule.get("schemaVersion").asInt()!=1)throw ApiValues.invalid();BigDecimal quantity=PricingValues.quantity(PricingValues.decimal(item.quantity()),item.scale());BigDecimal maximum=PricingValues.quantity(string(rule,"maximumUnitsPerPackage"),item.scale()),unit=ApiValues.quantity(string(rule,"unitWeightKg")),tare=new BigDecimal(string(rule,"tareWeightKg"));if(!string(rule,"tareWeightKg").matches("[0-9]{1,17}(\\.[0-9]{1,3})?")||tare.signum()<0)throw ApiValues.invalid();BigDecimal length=dimension(rule,"lengthCm"),width=dimension(rule,"widthCm"),height=dimension(rule,"heightCm");BigDecimal[] counts=quantity.divideAndRemainder(maximum);if(counts[0].compareTo(new BigDecimal(500-result.size()))>0)throw PricingValues.rule();int full=counts[0].intValueExact();for(int i=0;i<full;i++)result.add(parcel(item.skuId(),maximum,unit,tare,length,width,height));if(counts[1].signum()>0){if(result.size()>=500)throw PricingValues.rule();result.add(parcel(item.skuId(),counts[1],unit,tare,length,width,height));}}catch(com.nigson.shared.problem.Problem.Failure|ArithmeticException invalid){throw PricingValues.rule();}}return List.copyOf(result);}
 private static String string(JsonNode n,String key){var value=n.get(key);if(value==null||!value.isString())throw ApiValues.invalid();return value.asString();}
 private static BigDecimal dimension(JsonNode n,String key){BigDecimal value=ApiValues.money(string(n,key),true);if(value.signum()<=0)throw ApiValues.invalid();return value;}
 private static Parcel parcel(UUID id,BigDecimal quantity,BigDecimal unit,BigDecimal tare,BigDecimal l,BigDecimal w,BigDecimal h){BigDecimal weight=quantity.multiply(unit).add(tare);try{weight=weight.setScale(3,RoundingMode.UNNECESSARY);ApiValues.quantity(PricingValues.decimal(weight));}catch(ArithmeticException invalid){throw PricingValues.rule();}return new Parcel(id,PricingValues.decimal(quantity),PricingValues.decimal(weight),PricingValues.decimal(l),PricingValues.decimal(w),PricingValues.decimal(h));}
 public static String hash(Object value){var tree=EventCodec.JSON.valueToTree(value);if(EventCodec.JSON.writeValueAsBytes(tree).length>65536)throw PricingValues.rule();return EventCodec.hash(tree);}
}
